/**
 * CHIRP's icon — the helmeted cormorant — served by the hosted connector.
 *
 * Claude and its connector directory show the favicon from a server's own URL, so without one the connector appears
 * with a generic placeholder everywhere in Claude, whatever icon the directory listing carries. Embedded as base64
 * so the Worker needs no asset binding or bundler rule. 192×192 PNG.
 */
export const ICON_PNG_BASE64 =
  '';

export function iconBytes(): Uint8Array<ArrayBuffer> {
  const binary = atob(ICON_PNG_BASE64);
  const bytes = new Uint8Array(new ArrayBuffer(binary.length));
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}
